"""Researcher: gathers evidence within a fixed budget. Crustdata first; keyless fallbacks if it fails."""

from __future__ import annotations

from urllib.parse import urlparse

import neatlogs

from ..config import settings
from ..models import CompanyState, Evidence
from ..obs import emit
from ..resilience import Fatal, Retryable
from ..tools import crustdata, web

SKIP_HOSTS = (
    "linkedin.com",
    "facebook.com",
    "instagram.com",
    "twitter.com",
    "x.com",
    "youtube.com",
    "tiktok.com",
    "glassdoor.",
    "pinterest.",
    "reddit.com",
)


def _host(url: str) -> str:
    return (urlparse(url).hostname or "").removeprefix("www.")


def _next_id(state: CompanyState) -> str:
    return f"E{len(state.evidence) + 1}"


def _add(state: CompanyState, **kw) -> Evidence:
    ev = Evidence(id=_next_id(state), round=state.round, **kw)
    state.evidence.append(ev)
    return ev


def _search(query: str) -> tuple[list[dict], str]:
    try:
        return crustdata.web_search(query), "crustdata-web"
    except (Fatal, Retryable) as e:
        emit("recover", f"Crustdata search failed ({e}); falling back to DuckDuckGo", query=query)
        try:
            return web.search(query), "ddg"
        except Retryable as e2:
            emit("fail", f"search failed on both providers: {e2}", query=query)
            return [], "none"


def _fetch(urls: list[str]) -> list[dict]:
    pages: list[dict] = []
    try:
        pages = crustdata.web_fetch(urls)
    except (Fatal, Retryable) as e:
        emit("recover", f"Crustdata fetch failed ({e}); fetching {len(urls)} pages directly")
    got = {p["url"] for p in pages if p.get("success") and p.get("content")}
    missing = [u for u in urls if u not in got]
    if pages and missing:
        emit("recover", f"{len(missing)} pages empty via Crustdata; retrying them directly")
    for u in missing:
        try:
            page = web.fetch(u)
        except Retryable as e:
            emit("fail", f"could not fetch {u[:70]}: {e}")
            continue
        page["via"] = "direct"
        pages = [p for p in pages if p.get("url") != u] + [page]
    return pages


@neatlogs.span(kind="AGENT", name="researcher", role="researcher", goal="collect source evidence within budget")
def research(state: CompanyState, queries: list[tuple[str, str]]) -> list[Evidence]:
    before = len(state.evidence)

    if not any(e.kind == "crustdata" for e in state.evidence):
        try:
            record = crustdata.enrich_company(domain=state.domain, name=None if state.domain else state.company)
        except (Fatal, Retryable) as e:
            emit("recover", f"Crustdata enrichment unavailable ({e}); continuing with web sources only")
            record = None
        if record:
            text = crustdata.render_company(record)
            name = (record.get("basic_info") or {}).get("name") or state.company
            _add(state, kind="crustdata", url=f"crustdata://company/{record.get('crustdata_company_id', '')}",
                 title=f"Crustdata company record: {name}", text=text, via="crustdata")
            emit("crust", f"company record: {len(text.splitlines())} fields")
        else:
            emit("crust", "no Crustdata match for this company")

    budget = max(0, settings.max_searches - len(state.searched))
    candidates: list[tuple[str, str]] = []  # (url, question_id)
    company_host = (state.domain or "").removeprefix("www.")
    for qid, query in queries[:budget]:
        results, via = _search(query)
        state.searched.append(query)
        emit("web", f"search ({via}) '{query}' -> {len(results)} results")
        for r in results[:3]:
            if r.get("snippet"):
                _add(state, kind="snippet", url=r["url"], title=r.get("title", ""), text=r["snippet"], via=via,
                     question_ids=[qid])
        ranked = sorted(
            (r for r in results if not any(s in _host(r["url"]) for s in SKIP_HOSTS)),
            key=lambda r: (company_host and company_host in _host(r["url"])) is False,
        )
        for r in ranked[:2]:
            if r["url"] not in state.fetched and r["url"] not in {u for u, _ in candidates}:
                candidates.append((r["url"], qid))

    fetch_budget = max(0, settings.max_fetches - len(state.fetched))
    to_fetch = candidates[:fetch_budget]
    for i in range(0, len(to_fetch), 10):
        batch = to_fetch[i : i + 10]
        qid_by_url = dict(batch)
        for page in _fetch([u for u, _ in batch]):
            url = page.get("url", "")
            state.fetched.append(url)
            content = (page.get("content") or "").strip()
            if not content:
                continue
            _add(state, kind="page", url=url, title=page.get("title", ""), text=content[: settings.page_chars],
                 via=page.get("via", "crustdata-web"), question_ids=[qid_by_url.get(url, "")])

    new = state.evidence[before:]
    emit("web", f"round {state.round}: +{len(new)} evidence ({sum(e.kind == 'page' for e in new)} pages)")
    return new

"""Extractor: evidence -> atomic claims, each pinned to one evidence block and a quote from it."""

from __future__ import annotations

import neatlogs

from .. import llm
from ..models import FACT_FIELDS, Claim, CompanyState, Evidence, Extraction
from ..obs import emit


def _questions_text(state: CompanyState) -> str:
    return "\n".join(f"{q.id} (priority {q.priority}, {q.topic}): {q.question}" for q in state.plan.questions)


def _evidence_text(evidence: list[Evidence]) -> str:
    blocks = []
    for e in evidence:
        src = e.url if e.kind != "crustdata" else "Crustdata company database"
        blocks.append(f"[{e.id}] {e.kind} | {e.title} | {src}\n{e.text}")
    return "\n\n".join(blocks)


@neatlogs.span(kind="AGENT", name="extractor", role="claim extractor", goal="turn evidence into cited atomic claims")
def extract(state: CompanyState, evidence: list[Evidence]) -> list[Claim]:
    if not evidence:
        emit("extract", "no new evidence to extract from")
        return []
    out = llm.run_prompt(
        "extractor",
        {
            "company": state.company,
            "questions": _questions_text(state),
            "evidence": _evidence_text(evidence),
            "fields": ", ".join(FACT_FIELDS),
        },
        Extraction,
        role="fast",
        effort="low",
        max_tokens=16000,
        version=state.prompts_version,
    )
    known = {e.id for e in state.evidence}
    claims: list[Claim] = []
    dropped = 0
    for c in out.claims:
        if c.evidence_id not in known:
            dropped += 1
            continue
        field = c.field if c.field in FACT_FIELDS else None
        claims.append(Claim(id=f"C{len(state.claims) + len(claims) + 1}", round=state.round,
                            **c.model_dump(exclude={"field"}), field=field))
    if dropped:
        emit("extract", f"dropped {dropped} claims citing evidence ids that don't exist")
    state.claims.extend(claims)
    emit("extract", f"{len(claims)} claims from {len(evidence)} evidence blocks")
    return claims

"""Verifier: three independent checks before a claim may appear in a memo.

1. Grounding (deterministic): the quoted text must actually occur in the cited source.
2. Support (separate LLM judge): the source text around the quote must support the claim.
3. Consistency (deterministic): verified values for the same fact must agree across sources.
"""

from __future__ import annotations

import re

import neatlogs
from rapidfuzz import fuzz

from .. import llm
from ..models import Claim, CompanyState, Conflict, Judgements
from ..obs import emit

QUOTE_MIN_SCORE = 90.0
CONTEXT_CHARS = 400
JUDGE_BATCH = 25


def _norm(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


@neatlogs.span(kind="GUARDRAIL", name="quote_grounding")
def check_grounding(state: CompanyState, claims: list[Claim]) -> dict[str, str]:
    """Mark claims whose quote is (fuzzily) present in the cited evidence. Returns claim_id -> context."""
    by_id = {e.id: e for e in state.evidence}
    contexts: dict[str, str] = {}
    for c in claims:
        ev = by_id.get(c.evidence_id)
        quote = _norm(c.quote)
        if ev is None or len(quote) < 4:
            c.quote_found, c.quote_score = False, 0.0
            continue
        text = _norm(ev.text)
        if quote.lower() in text.lower():
            score, start, end = 100.0, text.lower().find(quote.lower()), 0
            end = start + len(quote)
        else:
            al = fuzz.partial_ratio_alignment(quote.lower(), text.lower())
            score, start, end = al.score, al.dest_start, al.dest_end
        c.quote_score = round(score, 1)
        c.quote_found = score >= QUOTE_MIN_SCORE
        if c.quote_found:
            contexts[c.id] = text[max(0, start - CONTEXT_CHARS) : end + CONTEXT_CHARS]
    grounded = sum(c.quote_found for c in claims)
    emit("verify", f"grounding: {grounded}/{len(claims)} quotes found in their cited source")
    return contexts


def _judge(state: CompanyState, claims: list[Claim], contexts: dict[str, str]) -> None:
    for i in range(0, len(claims), JUDGE_BATCH):
        batch = claims[i : i + JUDGE_BATCH]
        items = "\n\n".join(
            f"{c.id}\nclaim: {c.statement}\nquote: {c.quote}\nsource [{c.evidence_id}] text: ...{contexts[c.id]}..."
            for c in batch
        )
        out = llm.run_prompt("verifier", {"company": state.company, "items": items}, Judgements,
                             role="fast", effort="low", version=state.prompts_version)
        verdicts = {j.claim_id: j for j in out.judgements}
        for c in batch:
            j = verdicts.get(c.id)
            if j:
                c.support, c.reason = j.support, j.reason[:300]


# ---- consistency ------------------------------------------------------------------

_MULT = {"k": 1e3, "thousand": 1e3, "m": 1e6, "mn": 1e6, "million": 1e6, "b": 1e9, "bn": 1e9, "billion": 1e9}


def _number(v: str) -> float | None:
    m = re.search(r"(\d[\d,]*\.?\d*)\s*(k|thousand|mn|m|million|bn|b|billion)?\b", v.lower().replace("$", ""))
    if not m:
        return None
    n = float(m.group(1).replace(",", ""))
    return n * _MULT.get(m.group(2) or "", 1)


def _same(field: str, a: str, b: str) -> bool:
    if field == "founded_year":
        ya, yb = re.search(r"(19|20)\d\d", a), re.search(r"(19|20)\d\d", b)
        return not (ya and yb) or ya.group() == yb.group()
    if field in ("headcount", "total_funding_usd"):
        na, nb = _number(a), _number(b)
        if not na or not nb:
            return True
        tolerance = 0.30 if field == "headcount" else 0.25
        return abs(na - nb) / max(na, nb) <= tolerance
    if field in ("hq_city", "ceo"):
        na, nb = _norm(a).lower(), _norm(b).lower()
        return na in nb or nb in na or (field == "ceo" and na.split()[-1:] == nb.split()[-1:])
    return True


def find_conflicts(state: CompanyState) -> list[Conflict]:
    conflicts: list[Conflict] = []
    usable = [c for c in state.claims if c.support in ("supported", "partial") and c.field and c.value]
    for field in ("founded_year", "headcount", "total_funding_usd", "hq_city", "ceo"):
        group = [c for c in usable if c.field == field]
        for i, a in enumerate(group):
            for b in group[i + 1 :]:
                if a.evidence_id != b.evidence_id and not _same(field, a.value, b.value):
                    if any({a.id, b.id} <= set(x.claims) for x in conflicts):
                        continue
                    src = {e.id: e for e in state.evidence}
                    note = (f"{field}: '{a.value}' ({src[a.evidence_id].via}) vs "
                            f"'{b.value}' ({src[b.evidence_id].via})")
                    conflicts.append(Conflict(field=field, claims=[a.id, b.id], values=[a.value, b.value], note=note))
                    emit("conflict", note, field=field)
    return conflicts


@neatlogs.span(kind="AGENT", name="verifier", role="independent fact-checker", goal="reject claims the sources don't support")
def verify(state: CompanyState, claims: list[Claim]) -> None:
    contexts = check_grounding(state, claims)
    for c in claims:
        if not c.quote_found:
            c.support, c.reason = "unsupported", f"quote not found in cited source (match {c.quote_score:.0f}%)"
    to_judge = [c for c in claims if c.quote_found]
    if to_judge:
        _judge(state, to_judge, contexts)
    s = sum(c.support == "supported" for c in claims)
    p = sum(c.support == "partial" for c in claims)
    emit("verify", f"judge: {s} supported, {p} partial, {len(claims) - s - p} rejected of {len(claims)}")
    state.conflicts = find_conflicts(state)

